import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Row, Col, Label, FormGroup } from 'reactstrap';
import { Paper, CircularProgress } from '@material-ui/core';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import Skeleton from '@material-ui/lab/Skeleton';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import CustomSelect from 'components/CustomSelect';
import CustomInput from 'views/admin/Common/CustomInput';
import NoMatchPage from 'views/admin/Common/NoMatchPage.jsx';
import {
  UNOFFICIAL_BILL_PERIODS,
  UNOFFICIAL_BILL_TYPES,
  fetchUnofficialBillsService,
  createUnofficialBillService,
  showUnofficialBillReceiptService,
} from 'actions/admin/unofficialBill';
import { fetchSchoolStudentsPlainService } from 'actions/admin/students';
import { showToast } from 'actions/admin/auth';
import { formatMoney, formResMessage, getGlobalSchoolUtils, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import constants, { formStudentName, regNoStatic, courseStatic, PAYMENT_MODES } from 'config/constants';
import colors from 'config/colors';
import StatTile from 'views/admin/Common/StatTile';
import UnofficialBillFormModal from './UnofficialBillFormModal';

const PERIOD_OPTIONS = [
  { label: 'Monthly', value: UNOFFICIAL_BILL_PERIODS.MONTHLY },
  { label: 'Weekly', value: UNOFFICIAL_BILL_PERIODS.WEEKLY },
  { label: 'Custom', value: UNOFFICIAL_BILL_PERIODS.CUSTOM },
  { label: 'All', value: UNOFFICIAL_BILL_PERIODS.ALL },
];

// Built on render: regNoStatic/courseStatic follow the school's own labels, which are set after login.
const getTableHeaders = () => [
  'Receipt No',
  'Bill Date',
  'Payer',
  regNoStatic,
  courseStatic,
  'Type',
  'Mode',
  'Amount',
  'Remarks',
  'Receipt',
];

const labelFor = (options, value) => options.find(el => el.value === value)?.label || value || '--';

const today = () => moment().format('YYYY-MM-DD');

// Wrapped exactly like CustomInput (FormGroup + form-label) so the select's label and box sit on the same lines as
// the date and search inputs next to it.
const FieldSelect = ({ label, ...props }) => (
  <FormGroup>
    <Label className="form-label">{label}</Label>
    <CustomSelect noLabel {...props} />
  </FormGroup>
);

// Unofficial bills: money collected outside the official fee books, from a student or from anyone else (typed name).
// Admin role only - the sidebar entry is limited to it in AdminRoutes.jsx, but AdminApp doesn't check accessRoles
// for a plain route, so a direct URL is turned away here as well.
const UnofficialBillsPage = () => {
  const dispatch = useDispatch();
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const loggedUserSchool = useSelector(state => state.auth.loggedUserSchool);
  const loggedUserRole = useSelector(state => state.auth.loggedUserRole);
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const isAdmin = loggedUserRole === constants.roles.admin;
  const schoolId = loggedUserSchool || getGlobalSchoolUtils()?.schoolId;
  const { batchId } = getGlobalCurrentBatchUtils();

  const [period, setPeriod] = useState(UNOFFICIAL_BILL_PERIODS.MONTHLY);
  const [month, setMonth] = useState(() => moment().format('YYYY-MM'));
  const [weekDate, setWeekDate] = useState(today);
  const [fromDate, setFromDate] = useState(() => moment().startOf('month').format('YYYY-MM-DD'));
  const [toDate, setToDate] = useState(today);
  const [searchText, setSearchText] = useState('');
  const [report, setReport] = useState(null);
  const [isFetching, setIsFetching] = useState(false);
  const [students, setStudents] = useState([]);
  const [isStudentsFetching, setIsStudentsFetching] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [receiptBillId, setReceiptBillId] = useState(null);

  const showWarning = useCallback((message, type) => dispatch(showToast(message, type)), [dispatch]);

  // A half-picked period (cleared month, or a custom range with from after to) isn't sent to the backend.
  const periodError = (() => {
    if (period === UNOFFICIAL_BILL_PERIODS.MONTHLY && !month) return 'Select a month';
    if (period === UNOFFICIAL_BILL_PERIODS.WEEKLY && !weekDate) return 'Select a day in the week';
    if (period === UNOFFICIAL_BILL_PERIODS.CUSTOM) {
      if (!fromDate || !toDate) return 'Select both dates';
      if (fromDate > toDate) return 'From date must be on or before the to date';
    }
    return '';
  })();

  const fetchBills = useCallback(() => {
    if (!isAdmin || !schoolId) return;
    // Don't leave the last period's numbers up while the new one is incomplete.
    if (periodError) {
      setReport(null);
      return;
    }
    setIsFetching(true);
    fetchUnofficialBillsService({ schoolId, period, month, date: weekDate, fromDate, toDate, token: loggedUserToken })
      .then(data => setReport(data))
      .catch(err => {
        setReport(null);
        showWarning(formResMessage(err), 'error');
      })
      .finally(() => setIsFetching(false));
  }, [isAdmin, schoolId, period, month, weekDate, fromDate, toDate, periodError, loggedUserToken, showWarning]);

  useEffect(() => {
    fetchBills();
  }, [fetchBills]);

  // Every student of the current academic year, for the picker in the Add Bill modal.
  useEffect(() => {
    if (!isAdmin || !schoolId || !batchId) return;
    setIsStudentsFetching(true);
    fetchSchoolStudentsPlainService(schoolId, batchId, loggedUserToken)
      .then(data => setStudents(data?.content || []))
      .catch(err => console.error('err-fetchSchoolStudentsPlainService', err))
      .finally(() => setIsStudentsFetching(false));
  }, [isAdmin, schoolId, batchId, loggedUserToken]);

  const studentOptions = useMemo(
    () =>
      students.map(el => ({
        value: el.studentId,
        label: `${formStudentName(el)}${el.registerNumber ? ` (${el.registerNumber})` : ''}`,
      })),
    [students]
  );

  const submitCreateBill = postData => {
    setIsSaving(true);
    return createUnofficialBillService(
      { ...postData, schoolId, batchId, createdBy: loggedUserId || null },
      loggedUserToken
    )
      .then(bill => {
        showWarning(`Bill saved${bill?.receiptNumber ? ` - receipt ${bill.receiptNumber}` : ''}`, 'success');
        fetchBills();
      })
      .finally(() => setIsSaving(false));
  };

  const viewReceipt = bill => {
    setReceiptBillId(bill.billId);
    dispatch(
      showUnofficialBillReceiptService({
        schoolId,
        billId: bill.billId,
        receiptNumber: bill.receiptNumber,
        token: loggedUserToken,
      })
    )
      .catch(err => showWarning(err.message, 'error'))
      .finally(() => setReceiptBillId(null));
  };

  if (!isAdmin) return <NoMatchPage />;

  const search = searchText.trim().toLowerCase();
  const bills = (report?.bills || []).filter(
    item =>
      !search ||
      [item.payerName, item.studentName, item.registerNumber, item.receiptNumber].some(value =>
        (value || '').toLowerCase().includes(search)
      )
  );
  const tableHeaders = getTableHeaders();

  let rangeLabel = 'All dates';
  if (periodError || !report) rangeLabel = '--';
  else if (period !== UNOFFICIAL_BILL_PERIODS.ALL)
    rangeLabel = `${moment(report.fromDate).format('DD MMM, YYYY')} - ${moment(report.toDate).format('DD MMM, YYYY')}`;

  return (
    <div className="content">
      <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0', marginBottom: 16 }}>
        <div className="card-category font-weight-bold mb-3" style={{ overflow: 'hidden' }}>
          Unofficial Bills
          <div style={{ float: 'right' }}>
            <CustomButton
              size="small"
              name="+ Add Unofficial Bill"
              onClick={() => setIsModalOpen(true)}
              style={{ backgroundColor: colors.accent, color: colors.white }}
            />
          </div>
        </div>
        <Row>
          <Col sm={6} md={3} xl={2}>
            <FieldSelect
              label="Period"
              name="period"
              value={period}
              options={PERIOD_OPTIONS}
              onChange={(n, v) => setPeriod(v)}
            />
          </Col>
          {period === UNOFFICIAL_BILL_PERIODS.MONTHLY && (
            <Col sm={6} md={3} xl={2}>
              <CustomInput label="Month" name="month" type="month" value={month} onChange={(n, v) => setMonth(v)} />
            </Col>
          )}
          {period === UNOFFICIAL_BILL_PERIODS.WEEKLY && (
            <Col sm={6} md={3} xl={2}>
              <CustomInput
                label="Any day in the week"
                name="weekDate"
                type="date"
                value={weekDate}
                onChange={(n, v) => setWeekDate(v)}
              />
            </Col>
          )}
          {period === UNOFFICIAL_BILL_PERIODS.CUSTOM && (
            <>
              <Col sm={6} md={3} xl={2}>
                <CustomInput
                  label="From date"
                  name="fromDate"
                  type="date"
                  value={fromDate}
                  onChange={(n, v) => setFromDate(v)}
                />
              </Col>
              <Col sm={6} md={3} xl={2}>
                <CustomInput
                  label="To date"
                  name="toDate"
                  type="date"
                  min={fromDate}
                  value={toDate}
                  onChange={(n, v) => setToDate(v)}
                />
              </Col>
            </>
          )}
          <Col sm={12} md={6} xl={4}>
            <CustomInput
              label="Search"
              name="searchText"
              placeholder="Payer, student, reg no or receipt no..."
              value={searchText}
              onChange={(n, v) => setSearchText(v)}
            />
          </Col>
        </Row>
        {periodError && <div className="err-msg mb-3">{periodError}</div>}
        <hr style={{ margin: '4px 0 20px' }} />
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12 }}>
          <StatTile
            label="Bills"
            value={report?.totalBills ?? 0}
            tone="neutral"
            note={rangeLabel}
            loading={isFetching}
          />
          <StatTile
            label="Total collected"
            value={formatMoney(report?.totalAmount || 0)}
            tone="income"
            note={rangeLabel}
            loading={isFetching}
          />
        </div>
      </Paper>

      <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
        <div className="card-category font-weight-bold mb-3">Bills ({rangeLabel})</div>
        <div style={{ overflowX: 'auto' }}>
          <Table size="small" aria-label="a dense table">
            <TableHead>
              <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                {tableHeaders.map(header => (
                  <TableCell key={header} component="th" align="left">
                    <b>{header}</b>
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {isFetching ? (
                Array.from({ length: 4 }).map((_, i) => (
                  <TableRow key={i}>
                    {tableHeaders.map(header => (
                      <TableCell key={header}>
                        <Skeleton variant="text" />
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : bills.length ? (
                bills.map(item => (
                  <TableRow key={item.billId}>
                    <TableCell component="th" scope="row" style={{ whiteSpace: 'nowrap' }}>
                      {item.receiptNumber || '--'}
                    </TableCell>
                    <TableCell style={{ whiteSpace: 'nowrap' }}>
                      {item.billDate ? moment(item.billDate).format('DD MMM, YYYY') : '--'}
                    </TableCell>
                    <TableCell>
                      {/* A student bill shows the student under the payer (the payer is whoever paid). */}
                      <div>{item.payerName || '--'}</div>
                      <div style={{ fontSize: 11, color: '#6b778a' }}>
                        {item.studentId
                          ? `Student${
                              item.studentName && item.studentName !== item.payerName ? `: ${item.studentName}` : ''
                            }`
                          : 'Other'}
                      </div>
                    </TableCell>
                    <TableCell>{item.registerNumber || '--'}</TableCell>
                    <TableCell>{item.className || '--'}</TableCell>
                    <TableCell>{labelFor(UNOFFICIAL_BILL_TYPES, item.billType)}</TableCell>
                    <TableCell>{labelFor(PAYMENT_MODES, item.paymentMode)}</TableCell>
                    <TableCell style={{ whiteSpace: 'nowrap' }}>{formatMoney(item.amount)}</TableCell>
                    <TableCell>{item.remarks || '--'}</TableCell>
                    <TableCell align="center">
                      {receiptBillId === item.billId ? (
                        <CircularProgress size={15} />
                      ) : (
                        <span onClick={() => viewReceipt(item)} style={{ color: 'blue', cursor: 'pointer' }}>
                          <b>View</b>
                        </span>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={tableHeaders.length} style={{ textAlign: 'center', color: '#9a9a9a' }}>
                    {periodError ? 'Fix the period above to see bills.' : 'No unofficial bills for this period.'}
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
      </Paper>

      <UnofficialBillFormModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={submitCreateBill}
        isSaving={isSaving}
        studentOptions={studentOptions}
        isStudentsLoading={isStudentsFetching}
        showWarning={showWarning}
      />
    </div>
  );
};

export default UnofficialBillsPage;
