import React, { useEffect, useState } from 'react';
import moment from 'moment';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label } from 'reactstrap';
import { Radio } from '@material-ui/core';
import CustomButton from 'components/CustomButton';
import CustomSelect from 'components/CustomSelect';
import CustomInput from 'views/admin/Common/CustomInput';
import { formResMessage } from 'utils/commonFunc';
import { UNOFFICIAL_BILL_TYPES } from 'actions/admin/unofficialBill';
import { PAYMENT_MODES } from 'config/constants';
import colors from 'config/colors';

// Who the bill is for. The two are separate flows: a student bill sends only the studentId (the backend takes the
// payer name from the student), a bill for anyone else sends a typed payer name and no studentId.
const BILL_FOR = {
  STUDENT: {
    key: 'STUDENT',
    label: 'Student',
    icon: 'fas fa-user-graduate',
    description: 'Pick a student of the current academic year.',
  },
  OTHER: {
    key: 'OTHER',
    label: 'Someone else',
    icon: 'fas fa-user-edit',
    description: 'Type the payer’s name, e.g. a parent, visitor or donor.',
  },
};

// Field limits from the backend's CreateBillRequest.
const MAX_PAYER_NAME = 200;
const MAX_PAYER_PHONE = 20;
const MAX_REMARKS = 1000;

const today = () => moment().format('YYYY-MM-DD');

const emptyForm = () => ({
  studentId: null,
  payerName: '',
  payerPhone: '',
  billType: null,
  paymentMode: null,
  amount: '',
  billDate: today(),
  remarks: '',
});

const UnofficialBillFormModal = ({
  isOpen,
  onClose,
  onSubmit,
  isSaving = false,
  studentOptions = [],
  isStudentsLoading = false,
  showWarning,
}) => {
  const [billFor, setBillFor] = useState(BILL_FOR.STUDENT.key);
  const [form, setForm] = useState(emptyForm);
  const [errors, setErrors] = useState({});
  const isStudent = billFor === BILL_FOR.STUDENT.key;

  useEffect(() => {
    if (isOpen) {
      setBillFor(BILL_FOR.STUDENT.key);
      setForm(emptyForm());
      setErrors({});
    }
  }, [isOpen]);

  const handleChange = (name, value) => {
    setForm(prev => ({ ...prev, [name]: value }));
    setErrors(prev => ({ ...prev, [name]: '' }));
  };

  // The shared fields (type, mode, amount, date, remarks) carry over; only the "who" errors are cleared.
  const changeBillFor = key => {
    setBillFor(key);
    setErrors(prev => ({ ...prev, studentId: '', payerName: '', payerPhone: '' }));
  };

  const validate = () => {
    const err = {};
    if (isStudent) {
      if (!form.studentId) err.studentId = 'Select a student';
    } else {
      const name = form.payerName.trim();
      if (!name) err.payerName = 'Enter the payer’s name';
      else if (name.length > MAX_PAYER_NAME) err.payerName = `Keep the name under ${MAX_PAYER_NAME} characters`;
      const phone = form.payerPhone.trim();
      if (phone && !/^\+?[0-9 -]+$/.test(phone)) err.payerPhone = 'Enter a valid phone number';
      else if (phone.length > MAX_PAYER_PHONE) err.payerPhone = `Keep the phone under ${MAX_PAYER_PHONE} characters`;
    }
    if (!form.billType) err.billType = 'Select a bill type';
    if (!form.paymentMode) err.paymentMode = 'Select a payment mode';
    if (!form.amount || Number(form.amount) <= 0) err.amount = 'Enter a valid amount';
    if (!form.billDate) err.billDate = 'Select the bill date';
    if (form.remarks.trim().length > MAX_REMARKS) err.remarks = `Keep remarks under ${MAX_REMARKS} characters`;
    setErrors(err);
    return !Object.keys(err).length;
  };

  const handleSubmit = e => {
    e.preventDefault();
    if (!validate()) return;
    const postData = {
      studentId: isStudent ? form.studentId : null,
      payerName: isStudent ? null : form.payerName.trim(),
      payerPhone: isStudent ? null : form.payerPhone.trim() || null,
      billType: form.billType,
      paymentMode: form.paymentMode,
      amount: Number(form.amount),
      billDate: form.billDate,
      remarks: form.remarks.trim() || null,
    };
    onSubmit(postData)
      .then(() => onClose())
      .catch(err => showWarning?.(formResMessage(err), 'error'));
  };

  return (
    <Modal size="md" isOpen={isOpen}>
      <ModalHeader toggle={isSaving ? undefined : onClose}>Add Unofficial Bill</ModalHeader>
      <form onSubmit={handleSubmit}>
        <ModalBody>
          <Label>
            Bill for<sup> *</sup>
          </Label>
          <Row className="mb-2">
            {Object.values(BILL_FOR).map(item => {
              const checked = billFor === item.key;
              return (
                <Col key={item.key} sm={6} className="mb-2">
                  <div
                    role="radio"
                    aria-checked={checked}
                    tabIndex={0}
                    onClick={() => changeBillFor(item.key)}
                    onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && changeBillFor(item.key)}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 4,
                      height: '100%',
                      padding: '10px 12px',
                      borderRadius: 8,
                      border: `1.5px solid ${checked ? colors.accent : '#e0e0e0'}`,
                      backgroundColor: checked ? '#F5EDFB' : '#fff',
                      cursor: 'pointer',
                    }}>
                    <Radio checked={checked} size="small" style={{ color: colors.accent, padding: 2 }} />
                    <div>
                      <div style={{ fontWeight: 'bold', fontSize: 13 }}>
                        <i className={item.icon} style={{ marginRight: 6, color: colors.accent }} />
                        {item.label.toUpperCase()}
                      </div>
                      <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>{item.description}</div>
                    </div>
                  </div>
                </Col>
              );
            })}
          </Row>
          <Row>
            {isStudent ? (
              <Col md={12}>
                <div className="mb-3">
                  <CustomSelect
                    label="Student"
                    isRequired
                    name="studentId"
                    value={form.studentId}
                    options={studentOptions}
                    onChange={handleChange}
                    placeholder="Search & select student..."
                    loading={isStudentsLoading}
                    error={errors.studentId}
                    usePortal
                  />
                </div>
              </Col>
            ) : (
              <>
                <Col md={7}>
                  <CustomInput
                    label={
                      <>
                        Payer name<sup> *</sup>
                      </>
                    }
                    name="payerName"
                    placeholder="e.g. Ravi Kumar"
                    value={form.payerName}
                    onChange={handleChange}
                    error={errors.payerName}
                  />
                </Col>
                <Col md={5}>
                  <CustomInput
                    label="Phone (optional)"
                    name="payerPhone"
                    placeholder="Mobile number"
                    value={form.payerPhone}
                    onChange={handleChange}
                    error={errors.payerPhone}
                  />
                </Col>
              </>
            )}
            <Col md={6}>
              <div className="mb-3">
                <CustomSelect
                  label="Bill type"
                  isRequired
                  name="billType"
                  value={form.billType}
                  options={UNOFFICIAL_BILL_TYPES}
                  onChange={handleChange}
                  error={errors.billType}
                  usePortal
                />
              </div>
            </Col>
            <Col md={6}>
              <div className="mb-3">
                <CustomSelect
                  label="Payment mode"
                  isRequired
                  name="paymentMode"
                  value={form.paymentMode}
                  options={PAYMENT_MODES}
                  onChange={handleChange}
                  error={errors.paymentMode}
                  usePortal
                />
              </div>
            </Col>
            <Col md={6}>
              <CustomInput
                type="number"
                label={
                  <>
                    Amount<sup> *</sup>
                  </>
                }
                name="amount"
                placeholder="Enter amount"
                min={0}
                value={form.amount}
                onChange={handleChange}
                error={errors.amount}
              />
            </Col>
            <Col md={6}>
              <CustomInput
                type="date"
                label={
                  <>
                    Bill date<sup> *</sup>
                  </>
                }
                name="billDate"
                value={form.billDate}
                onChange={handleChange}
                error={errors.billDate}
              />
            </Col>
            <Col md={12}>
              <CustomInput
                type="textarea"
                rows={3}
                label="Remarks (optional)"
                name="remarks"
                placeholder="Any extra detail"
                value={form.remarks}
                onChange={handleChange}
                error={errors.remarks}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={isSaving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            loading={isSaving}
            disabled={isSaving}
            name="Save"
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default UnofficialBillFormModal;
